/* Pure-TAN WCS for the browser (overlays, cursor readout, grid lines only).
 * The common display grid is pure TAN by construction; SIP or other distortions are
 * refused rather than approximated. Parity with astropy is checked in tanwcs.test.ts
 * against fixtures/wcs/tan_cases.json (generated by backend/scripts/make_wcs_fixtures.py).
 * Pixel convention: 0-based, integer values at pixel centres; FITS CRPIX is 1-based. */
import { applyOffsetsMas, offsetsMas, MAS_PER_RAD } from './tangent'

export interface WcsLike {
  header: Record<string, number | string>
  shape?: [number, number]
}

export class TanWcs {
  readonly crval: [number, number]
  readonly crpix0: [number, number] // 0-based reference pixel
  readonly cd: [[number, number], [number, number]] // deg / px
  private readonly inv: [[number, number], [number, number]]
  readonly shape: [number, number] | null

  constructor(desc: WcsLike) {
    const h = desc.header
    const ctype1 = String(h.CTYPE1 ?? '')
    const ctype2 = String(h.CTYPE2 ?? '')
    if (ctype1 !== 'RA---TAN' || ctype2 !== 'DEC--TAN') {
      throw new Error(`Browser WCS supports pure TAN only (got ${ctype1}/${ctype2}).`)
    }
    const num = (k: string) => {
      const v = Number(h[k])
      if (!Number.isFinite(v)) throw new Error(`WCS keyword ${k} missing`)
      return v
    }
    this.crval = [num('CRVAL1'), num('CRVAL2')]
    this.crpix0 = [num('CRPIX1') - 1, num('CRPIX2') - 1]
    this.cd = [
      [num('CD1_1'), num('CD1_2')],
      [num('CD2_1'), num('CD2_2')],
    ]
    const det = this.cd[0][0] * this.cd[1][1] - this.cd[0][1] * this.cd[1][0]
    if (det === 0) throw new Error('Singular CD matrix')
    this.inv = [
      [this.cd[1][1] / det, -this.cd[0][1] / det],
      [-this.cd[1][0] / det, this.cd[0][0] / det],
    ]
    this.shape = desc.shape ?? null
  }

  /** 0-based pixel -> (ra, dec) degrees. CD maps pixels to intermediate (east = +RA, north) degrees. */
  pixelToSky(x: number, y: number): [number, number] {
    const dx = x - this.crpix0[0]
    const dy = y - this.crpix0[1]
    const xiDeg = this.cd[0][0] * dx + this.cd[0][1] * dy
    const etaDeg = this.cd[1][0] * dx + this.cd[1][1] * dy
    return applyOffsetsMas(xiDeg * 3.6e6, etaDeg * 3.6e6, this.crval[0], this.crval[1])
  }

  /** (ra, dec) degrees -> 0-based pixel. */
  skyToPixel(ra: number, dec: number): [number, number] {
    const [e, n] = offsetsMas(ra, dec, this.crval[0], this.crval[1])
    const xi = e / 3.6e6
    const eta = n / 3.6e6
    return [this.crpix0[0] + this.inv[0][0] * xi + this.inv[0][1] * eta, this.crpix0[1] + this.inv[1][0] * xi + this.inv[1][1] * eta]
  }

  /** Mean pixel scale in arcsec / px. */
  get pixelScaleArcsec(): number {
    const det = Math.abs(this.cd[0][0] * this.cd[1][1] - this.cd[0][1] * this.cd[1][0])
    return Math.sqrt(det) * 3600
  }
}

export { MAS_PER_RAD }
